const COPPER = "#d69771";
const SILVER = "#aba7a8";
const BLUISH = "#456FA1";
const GOLD = "#c7a24a";


export class Discovery32UniformPack extends BaseTngEraUniformPack implements IUniformPack {

    constructor() {
        super(UniformEra.Discovery32);
    }

    getUniformSwatches() {
        return [
            new Swatch(BodyType.AverageMale, "Average Male", (token) => UniformCatalog.decorateSwatch(this.getUniformAndVariantByBodyType(token, token.variant, BodyType.AverageMale), BodyType.AverageMale, token), "BodyType.averageMale"),
            new Swatch(BodyType.AverageFemale, "Average Female", (token) => UniformCatalog.decorateSwatch(this.getUniformAndVariantByBodyType(token, token.variant, BodyType.AverageFemale), BodyType.AverageFemale, token), "BodyType.averageFemale")
        ];
    }

    getUniformVariantSwatches(token: Token) {
        return [];
    }

    getUniformAndVariantBody(token: Token) {
        return this.getUniformAndVariantByBodyType(token, token.variant, token.bodyType);
    }

    getUniformAndVariantByBodyType(token: Token, variant: UniformVariantType, bodyType: BodyType) {
        let base = "";
        let divisionColour = token.divisionColor;
        if (bodyType === BodyType.AverageMale) {
            base = Discovery32CenturyUniform.maleBody.replace(DefaultRed, divisionColour).replace(SpeciesRestrictions.DEFAULT_SKIN_COLOR_REGEX, token.skinColor);
        } else {
            base = Discovery32CenturyUniform.femaleBody.replace(DefaultRed, divisionColour).replace(SpeciesRestrictions.DEFAULT_SKIN_COLOR_REGEX, token.skinColor);
        }

        let metalHighlights = COPPER
        if (DivisionColors.getDivision(this.era, token.divisionColor) === 'Command') {
            metalHighlights = COPPER;
        } else if (DivisionColors.getDivision(this.era, token.divisionColor) === 'Science') {
            metalHighlights = BLUISH;
        } else if (DivisionColors.getDivision(this.era, token.divisionColor) === 'Operations') {
            metalHighlights = GOLD;
        } else if (DivisionColors.getDivision(this.era, token.divisionColor) === 'Medical') {
            metalHighlights = SILVER;
        }

        base = base.replace(/#d69771/g, metalHighlights);

        return this.getNeck(bodyType, token.skinColor, token.species, UniformEra.DominionWar) + base;

    }

    getRankIndicator(token: Token) {
        return "";
    }

    getBorderLogo(token: Token): string {
        let base = borderInsignia.base;
        return base + borderInsignia.shine;
    }

    getBorderColor(token: Token): string {
        return token.divisionColor;
    }

    getRankBorderIndicator(token: Token): string {
        return rankIndicators.border[Rank[token.rankIndicator]] ?? "";
    }
}